GITIGNORE_APPEND = '# QPX automated operations runtime and reports\nqpx_bot/operations_runtime/\nreports/qpx_operations/\n'
TARGETS = [*FILES, ".gitignore"]
originals: dict[str, bytes | None] = {}


def run(command: list[str]) -> None:
    print("$ " + " ".join(command))
    subprocess.run(command, cwd=ROOT, check=True)


def is_tracked(relative: str) -> bool:
    return subprocess.run(
        ["git", "ls-files", "--error-unmatch", relative],
        cwd=ROOT,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    ).returncode == 0


def ensure_targets_are_safe() -> None:
    changed: list[str] = []

    for relative in TARGETS:
        path = ROOT / relative
        worktree = subprocess.run(
            ["git", "diff", "--quiet", "--", relative],
            cwd=ROOT,
        )
        staged = subprocess.run(
            ["git", "diff", "--cached", "--quiet", "--", relative],
            cwd=ROOT,
        )

        if worktree.returncode != 0 or staged.returncode != 0:
            changed.append(relative)
            continue

        if (
            relative in FILES
            and path.exists()
            and not is_tracked(relative)
        ):
            changed.append(relative)

    if changed:
        raise RuntimeError(
            "These target files contain local changes and were "
            "not overwritten:\n" + "\n".join(changed)
        )


def preserve(relative: str) -> None:
    if relative in originals:
        return

    path = ROOT / relative
    originals[relative] = (
        path.read_bytes()
        if path.exists()
        else None
    )

    if path.exists():
        backup_path = BACKUP / relative
        backup_path.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, backup_path)


def install_files() -> None:
    for relative, content in FILES.items():
        preserve(relative)
        path = ROOT / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(
            textwrap.dedent(content).strip() + "\n",
            encoding="utf-8",
        )

        if path.suffix == ".sh":
            path.chmod(0o700)

        print(f"Installed: {relative}")


def patch_gitignore() -> None:
    relative = ".gitignore"
    preserve(relative)
    path = ROOT / relative
    content = path.read_text(encoding="utf-8")
    addition = textwrap.dedent(
        GITIGNORE_APPEND
    ).strip()

    if addition not in content:
        content = content.rstrip() + "\n\n" + addition + "\n"
        path.write_text(content, encoding="utf-8")
        print("Updated: .gitignore")


def restore() -> None:
    print("Restoring previous target files...")

    for relative, original in originals.items():
        path = ROOT / relative

        if original is None:
            if path.exists():
                path.unlink()
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(original)


def commit_and_push() -> None:
    paths = list(TARGETS)

    try:
        paths.append(
            str(Path(__file__).resolve().relative_to(ROOT))
        )
    except ValueError:
        pass

    run(["git", "add", "--", *paths])

    staged = subprocess.run(
        ["git", "diff", "--cached", "--quiet"],
        cwd=ROOT,
    )

    if staged.returncode == 0:
        print("Automated daily operations are already committed.")
        return

    run([
        "git",
        "commit",
        "-m",
        "Implement QPX Bot automated daily operations",
    ])

    branch = subprocess.check_output(
        ["git", "branch", "--show-current"],
        cwd=ROOT,
        text=True,
    ).strip()

    if not branch:
        raise RuntimeError("Cannot push from detached Git state.")

    run(["git", "push", "origin", branch])


def main() -> int:
    print("=" * 78)
    print("QPX BOT — AUTOMATED DAILY OPERATIONS INSTALLER V3")
    print("=" * 78)
    print(f"Project: {ROOT}")

    ensure_targets_are_safe()
    install_files()
    patch_gitignore()

    try:
        run([
            sys.executable,
            "-m",
            "tests.test_qpx_bot_daily_operations",
        ])
        run([sys.executable, "tests/run_all_tests.py"])
    except Exception:
        restore()
        raise

    commit_and_push()

    print()
    print("Installing the Termux cron schedule...")
    print()

    try:
        run([
            sys.executable,
            "QPX_SETUP_DAILY_SCHEDULE.py",
            "--install",
        ])
    except Exception:
        print()
        print("=" * 78)
        print("QPX DAILY OPERATIONS CODE: INSTALLED AND PUSHED")
        print("TERMUX SCHEDULE: NEEDS RETRY")
        print("=" * 78)
        print(
            "Re-run:\n"
            "python QPX_SETUP_DAILY_SCHEDULE.py --install"
        )
        return 2

    print()
    print("Writing the first health snapshot...")
    print()

    try:
        run([
            sys.executable,
            "QPX_RUN_DAILY_OPERATIONS.py",
            "--check-only",
        ])
    except Exception:
        print()
        print("=" * 78)
        print("QPX DAILY OPERATIONS + SCHEDULE: INSTALLED")
        print("INITIAL HEALTH SNAPSHOT: NEEDS RETRY")
        print("=" * 78)
        print(
            "Re-run:\n"
            "python QPX_RUN_DAILY_OPERATIONS.py --check-only"
        )
        return 3

    print()
    print("=" * 78)
    print("QPX AUTOMATED DAILY OPERATIONS: COMPLETE")
    print("=" * 78)
    print(
        "The schedule checks hourly on weekday evenings and "
        "executes only once per completed market session."
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
